function pulseGates(grid, period) {
  const rows = grid.length;
  const cols = grid[0].length;
  const moves = [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]];
  let here = new Set();
  let goal = -1;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === "S") here.add(r * cols + c);
      if (grid[r][c] === "E") goal = r * cols + c;
    }
  }
  const limit = rows * cols * period;
  for (let time = 1; time <= limit; time++) {
    const after = new Set();
    for (const cell of here) {
      const r = Math.floor(cell / cols);
      const c = cell % cols;
      for (const [dr, dc] of moves) {
        const nr = r + dr;
        const nc = c + dc;
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
        const ch = grid[nr][nc];
        if (ch === "#") continue;
        if (ch >= "0" && ch <= "9" && Number(ch) !== time % period) continue;
        after.add(nr * cols + nc);
      }
    }
    if (after.has(goal)) return time;
    here = after;
  }
  return -1;
}

function pulseGates(grid, period) {
  const rows = grid.length;
  const cols = grid[0].length;
  const flat = grid.join("");
  const start = flat.indexOf("S");
  const goal = flat.indexOf("E");
  const states = rows * cols * period;
  const seen = new Uint8Array(states);
  const queueCell = new Int32Array(states);
  const queueTime = new Int32Array(states);
  const moves = [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]];
  let head = 0;
  let tail = 0;
  seen[start * period] = 1;
  queueCell[tail] = start;
  queueTime[tail] = 0;
  tail++;
  while (head < tail) {
    const cell = queueCell[head];
    const time = queueTime[head];
    head++;
    if (cell === goal) return time;
    const r = Math.floor(cell / cols);
    const c = cell % cols;
    const nextTime = time + 1;
    const beat = nextTime % period;
    for (const [dr, dc] of moves) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
      const next = nr * cols + nc;
      const code = flat.charCodeAt(next);
      if (code === 35) continue;
      if (code >= 48 && code <= 57 && code - 48 !== beat) continue;
      if (seen[next * period + beat] === 1) continue;
      seen[next * period + beat] = 1;
      queueCell[tail] = next;
      queueTime[tail] = nextTime;
      tail++;
    }
  }
  return -1;
}
